//Tag.
var players = 2;//Change if you want
var playerPositions = [];
for (var i = 0; i < players; i++) {
    playerPositions.push({x: 100+300*i % 600, y: random(100, 500), it: false});
}

textFont(createFont("Calibri"));
function drawPlayers() {
    for (var i = 0; i < playerPositions.length; i++) {
        fill(abs(sin(i*90)*255), cos(i*45)*255, 0);
        rect(playerPositions[i].x, playerPositions[i].y, 50, 50);
        if (playerPositions[i].it === true) {
            fill(0);
            textSize(30);
            text("IT", playerPositions[i].x + 17, playerPositions[i].y + 34);
        }
    }
}

var playerXArray = [];
var playerYArray = [];

function movePlayers() {
    var Player = playerPositions[0];
    var AI = playerPositions[1];
    //Player moving
    var speed = 3;
    if (keyIsPressed) {
        if (String(key).toUpperCase() === "W") {
            Player.y-=speed;
        } else if (String(key).toUpperCase() === "A") {
            Player.x-=speed;
        } else if (String(key).toUpperCase() === "S") {
            Player.y+=speed;
        } else if (String(key).toUpperCase() === "D") {
            Player.x+=speed;
        }
    }
    playerXArray.push(Player.x);
    playerYArray.push(Player.y);
    var delay = floor(random(5, 50));
    if (AI.x < playerXArray[max(0, frameCount-delay)]) {
        AI.x += speed;
    }
    if (AI.x > playerXArray[max(0, frameCount-delay)]) {
        AI.x -= speed;
    }
    if (AI.y < playerYArray[max(0, frameCount-delay)]) {
        AI.y += speed;
    }
    if (AI.y > playerYArray[max(0, frameCount-delay)]) {
        AI.y -= speed;
    }

    if (Player.x > AI.x - 50 && Player.x < AI.x + 50 && Player.y > AI.y - 50 && Player.y < AI.y + 50) {
        Program.restart();
    }
}

function chooseIt() {
    playerPositions[floor(random(playerPositions.length))].it = true;
}

